using System;
internal static class UsbAdmissionTabPipeTest {
 static void Check(bool ok){if(!ok)throw new Exception("Tab pipe regression");}static bool Reject(Action action){try{action();return false;}catch{return true;}}
 public static int Main(){string name="sentinel-usb-tab-"+new string('a',32);UsbAdmissionTabPipe.ValidateName(name);Check(Reject(()=>UsbAdmissionTabPipe.ValidateName(name+"/x")));Check(Reject(()=>UsbAdmissionTabPipe.ValidateName("sentinel-usb-tab-"+new string('A',32))));var nonce=new byte[16];nonce[0]=1;var frame=UsbAdmissionTabPipe.Encode("{\"method\":\"status\"}",nonce);Check(UsbAdmissionTabPipe.Decode(frame,nonce)=="{\"method\":\"status\"}");var other=(byte[])nonce.Clone();other[0]=2;Check(Reject(()=>UsbAdmissionTabPipe.Decode(frame,other)));Check(Reject(()=>UsbAdmissionTabPipe.Encode(new string('x',32769),nonce)));Check(Reject(()=>UsbAdmissionTabPipe.Encode("x",new byte[16])));Check(Reject(()=>UsbAdmissionTabPipe.Encode("\ud800",nonce)));var invalid=(byte[])frame.Clone();invalid[0]=0;Check(Reject(()=>UsbAdmissionTabPipe.Decode(invalid,nonce)));invalid=(byte[])frame.Clone();invalid[24]=255;invalid[25]=255;invalid[26]=255;invalid[27]=255;Check(Reject(()=>UsbAdmissionTabPipe.Decode(invalid,nonce)));var trailing=new byte[frame.Length+1];Buffer.BlockCopy(frame,0,trailing,0,frame.Length);Check(Reject(()=>UsbAdmissionTabPipe.Decode(trailing,nonce)));UsbAdmissionTabPipe.ValidatePeer(1,2,3,1,2,3);Check(Reject(()=>UsbAdmissionTabPipe.ValidatePeer(1,2,3,4,2,3)));Check(Reject(()=>UsbAdmissionTabPipe.ValidatePeer(1,2,3,1,4,3)));Check(Reject(()=>UsbAdmissionTabPipe.ValidatePeer(1,2,3,1,2,4)));Console.WriteLine("PASS bounded strict UTF8 framing, nonce reply binding, pipe names and PID/start/session refusal gates; no native pipe or privileged action");return 0;}
}
